css:
@media print {
    .page-footer {
        position: fixed;
        bottom: -15mm;
        right: -15mm;
        font-size: 9pt;
        color: #666;
    }

    /* 페이지 카운터를 위한 설정 */
    @page {
        @bottom-right {
            content: "Page " counter(page);
            font-size: 9pt;
            color: #666;
        }
    }
}
